blocks.content:
1.chips {
2    display: flex;
3    list-style-type: none;
4    padding: 12px 0;
5    justify-content: space-around;
6}
7
8.chip {
9    border-radius: 12px;
10    padding: 10px;
11    font-size: 15px;
12    background-color: #eaeaec;
13    font-weight: 600;
14    transition: all 0.3s ease-in-out;
15}
16
17.chip:hover {
18    background-color: #7370f4;
19    color: white;
20    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
21}

1.action-button {
2    border-top: 1px solid #eaeaec;
3    padding-top: 16px;
4    gap: 12px;
5    display: flex;
6    flex-direction: column;
7}
8
9.action-button a {
10    background-color: #29283f;
11    color: white;
12    padding: 12px;
13    text-decoration: none;
14    border-radius: 12px;
15    font-size: 18px;
16    display: flex;
17    justify-content: center;
18    align-items: center;
19    transition: transform 0.2s ease-in-out;
20}
21
22.action-button a:hover {
23    transform: scale(1.05);
24}
25
26.action-button a.secondary {
27    background-color: inherit;
28    color: #29283f;
29    border: 1px solid #29283f;
30}
